import React from 'react';
import { SolutionResponse } from '../../types';
import { CheckCircle, XCircle, Info, TrendingUp, Award } from 'lucide-react';

interface ResultsDisplayProps {
    result: SolutionResponse;
}

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ result }) => {
    return (
        <div className="space-y-6">
            {/* Статус диагонального преобладания */}
            <div className={`p-4 rounded-lg border ${
                result.diagonalDominance
                    ? 'bg-green-50 border-green-200'
                    : 'bg-yellow-50 border-yellow-200'
            }`}>
                <div className="flex items-center gap-2">
                    {result.diagonalDominance ? (
                        <CheckCircle className="w-5 h-5 text-green-600" />
                    ) : (
                        <XCircle className="w-5 h-5 text-yellow-600" />
                    )}
                    <span className={result.diagonalDominance ? 'text-green-700' : 'text-yellow-700'}>
                        {result.diagonalDominance
                            ? '✓ Диагональное преобладание выполнено'
                            : '⚠ Диагональное преобладание не выполнено (но решение найдено)'}
                    </span>
                </div>
            </div>

            {/* Основные характеристики */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-lg border border-purple-200">
                    <div className="flex items-center gap-2 text-purple-700 mb-1">
                        <Award className="w-4 h-4" />
                        <span className="text-sm font-medium">Определитель</span>
                    </div>
                    <div className="text-xl font-mono font-bold text-purple-900">
                        {result.determinant.toExponential(6)}
                    </div>
                </div>

                <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-4 rounded-lg border border-blue-200">
                    <div className="flex items-center gap-2 text-blue-700 mb-1">
                        <TrendingUp className="w-4 h-4" />
                        <span className="text-sm font-medium">Норма матрицы</span>
                    </div>
                    <div className="text-xl font-mono font-bold text-blue-900">
                        {result.matrixNorm.toFixed(4)}
                    </div>
                </div>

                <div className="bg-gradient-to-br from-green-50 to-green-100 p-4 rounded-lg border border-green-200">
                    <div className="flex items-center gap-2 text-green-700 mb-1">
                        <Info className="w-4 h-4" />
                        <span className="text-sm font-medium">Итераций</span>
                    </div>
                    <div className="text-xl font-mono font-bold text-green-900">
                        {result.iterations}
                    </div>
                </div>
            </div>

            {/* Вектор решения */}
            <div className="bg-gray-50 rounded-lg p-4 border">
                <h3 className="text-lg font-medium mb-3 flex items-center gap-2">
                    <span className="w-1 h-5 bg-blue-600 rounded-full"></span>
                    Вектор неизвестных x:
                </h3>
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                    {result.solution.map((value, index) => (
                        <div key={index} className="bg-white p-3 rounded-md shadow-sm border">
                            <div className="text-xs text-gray-500 mb-1">x<sub>{index + 1}</sub></div>
                            <div className="font-mono font-medium text-lg">{value.toFixed(8)}</div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Вектор невязки */}
            <div className="bg-gray-50 rounded-lg p-4 border">
                <h3 className="text-lg font-medium mb-3 flex items-center gap-2">
                    <span className="w-1 h-5 bg-red-600 rounded-full"></span>
                    Вектор невязки:
                </h3>
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                    {result.residual.map((value, index) => (
                        <div key={index} className="bg-red-50 p-3 rounded-md shadow-sm border border-red-100">
                            <div className="text-xs text-red-500 mb-1">r<sub>{index + 1}</sub></div>
                            <div className="font-mono font-medium text-red-700">
                                {value.toExponential(4)}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Информация о сходимости */}
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <div className="flex items-start gap-2">
                    <Info className="w-5 h-5 text-blue-600 mt-0.5 flex-shrink-0" />
                    <div>
                        <p className="text-sm text-blue-800 font-medium">
                            {result.message}
                        </p>
                        <p className="text-xs text-blue-600 mt-1">
                            Максимальная погрешность на последней итерации:{' '}
                            {result.iterationHistory && result.iterationHistory.length > 0
                                ? result.iterationHistory[result.iterationHistory.length - 1].maxError.toExponential(4)
                                : 'N/A'}
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};
